head.script:
scwin.count = 0;
scwin.onpageload = function () {
    scwin.count++;
    var tmpSrc1 = scwin.getfolderPath() + "/sub_red.xml";
    var tmpSrc2 = scwin.getfolderPath() + "/sub_green.xml";
    var tmpSrc3 = scwin.getfolderPath() + "/sub_blue.xml";
    var tmpSrc4 = scwin.getfolderPath() + "/sub_yellow.xml";

    windowContainer1.createWindow({
        "title": "Red - " + scwin.count,
        "src": tmpSrc1,
        "windowId": "red",
        "frameMode": "wframe"
    });
    windowContainer1.createWindow({
        "title": "Green - " + scwin.count,
        "src": tmpSrc2,
        "windowId": "green",
        "frameMode": "wframe"
    });
    windowContainer1.createWindow({
        "title": "Blue - " + scwin.count,
        "src": tmpSrc3,
        "windowId": "blue",
        "frameMode": "wframe"
    });
    windowContainer1.createWindow({
        "title": "Yellow - " + scwin.count,
        "src": tmpSrc4,
        "windowId": "yellow",
        "frameMode": "wframe",
    });
    windowContainer1.setArrangeWindows("vertical");
};

scwin.onpageunload = function () {

};


scwin.trigger1_onclick = function (e) {
    windowContainer1.setArrangeWindows("vertical", ["red", "yellow", "green"]);
};

scwin.trigger2_onclick = function (e) {
    windowContainer1.setArrangeWindows("horizontal", ["blue", "red", "green"]);

};

scwin.trigger3_onclick = function (e) {
    windowContainer1.setArrangeWindows("cascade", ["red", "blue", "green"]);

};

scwin.trigger4_onclick = function (e) {
    windowContainer1.setArrangeWindows("sequential", ["blue", "green", "red"]);

};
scwin.getfolderPath = function () {

    var currentPath = window.location.href;
    var folderPath;

    if (currentPath.includes("mainContainer")) {
        console.log("true  ===> " + $p.getFrameId());
        const cmtFrame = $p.getComponentById($p.getFrameId());
        currentPath = cmtFrame.getSrc();
        folderPath = currentPath.substring(0, currentPath.lastIndexOf('/'));
    } else {
        console.log("false  ===> ");
        folderPath = currentPath.split('w2xPath=')[1].substring(0, currentPath.split('w2xPath=')[1].lastIndexOf('/'));
    }
    return folderPath;
};
